import java.util.*;

class Solution {
    public ListNode reverseList(ListNode head) {
        List<Integer> vals = new ArrayList<>();
        for (ListNode p = head; p != null; p = p.next) {
            vals.add(p.val);
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (int i = vals.size() - 1; i >= 0; i--) {
            tail.next = new ListNode(vals.get(i));
            tail = tail.next;
        }
        return dummy.next;
    }
}

class Solution {
    public ListNode reverseList(ListNode head) {
        // 空链表或单节点，反转后就是自己
        if (head == null || head.next == null) return head;

        // 先反转后半段，newHead 是最终的头
        ListNode newHead = reverseList(head.next);

        // 此时 head.next 已成为反转段的尾节点，让它指回 head
        head.next.next = head;
        // 必须断开，否则 head 与其后继互相指向形成环
        head.next = null;

        return newHead;
    }
}

class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode prev = null;
        ListNode curr = head;

        while (curr != null) {
            ListNode next = curr.next;   // 1. 先存后继，这一步不能放到后面
            curr.next = prev;            // 2. 掉头
            prev = curr;                 // 3. 已反转部分前移
            curr = next;                 // 4. 继续下一个
        }
        // 结束时 curr 为 null，prev 才是新的头
        return prev;
    }
}
